<?php
namespace App\Http\Controllers; use App\Models\Experience; use App\Models\Comment; use App\Models\Bookmark; use App\Models\ExperienceLike; use Illuminate\Http\Request;
class EngagementController extends Controller {public function like(Experience $experience){abort_unless($experience->status==='published',404);$like=ExperienceLike::where('experience_id',$experience->id)->where('user_id',auth()->id())->first();$like?$like->delete():ExperienceLike::create(['experience_id'=>$experience->id,'user_id'=>auth()->id()]);return back()->with('success',$like?'Like removed.':'Experience liked.');} public function bookmark(Experience $experience){abort_unless($experience->status==='published',404);$b=Bookmark::where('experience_id',$experience->id)->where('user_id',auth()->id())->first();$b?$b->delete():Bookmark::create(['experience_id'=>$experience->id,'user_id'=>auth()->id()]);return back()->with('success',$b?'Bookmark removed.':'Experience bookmarked.');} public function comment(Request $r,Experience $experience){abort_unless($experience->status==='published',404);$data=$r->validate(['body'=>'required|string|min:2|max:3000','parent_id'=>'nullable|integer|exists:comments,id']);if(!empty($data['parent_id']))abort_unless(Comment::where('id',$data['parent_id'])->where('experience_id',$experience->id)->exists(),422);$experience->allComments()->create(['user_id'=>$r->user()->id,'body'=>$data['body'],'parent_id'=>$data['parent_id']??null]);return back()->with('success','Comment posted.');} public function bookmarks(){ $experiences=auth()->user()->bookmarks()->with(['experience.exam','experience.user'])->latest()->paginate(15);return view('profile.bookmarks',compact('experiences'));} }
